import sqlite3
import sys
import argparse

def parse_filters(filters):
    and_filters = []
    for line in filters:
        if not line.strip():
            continue
        parts = line.split('=', 1)
        if len(parts) != 2:
            continue
        column, value = parts
        and_filters.append((column, value))
    return and_filters

def query_tasks(db_conn, filters):
    query = "SELECT id, title, status, owner FROM tasks"
    params = []
    placeholders = []
    for col, val in filters:
        if col == 'id':
            query += " WHERE id = ?"
            placeholders.append(val)
        elif col == 'title':
            query += " WHERE title = ?"
            placeholders.append(val)
        elif col == 'status':
            query += " WHERE status = ?"
            placeholders.append(val)
        elif col == 'owner':
            query += " WHERE owner = ?"
            placeholders.append(val)
        else:
            continue
        if placeholders:
            params.extend(placeholders)
            placeholders = []
    if placeholders:
        query += " WHERE 1=1"
        params.extend(placeholders)
    cursor = db_conn.cursor()
    cursor.execute(query, params)
    return cursor.fetchall()

