import sys
import sqlite3
import re

def main():
    token_file = sys.argv[1]
    with open(token_file, 'r') as f:
        token = f.read().strip()

    conn = sqlite3.connect('app.db')
    cursor = conn.cursor()

    cursor.execute("SELECT role FROM tokens WHERE token = ?", (token,))
    result = cursor.fetchone()

    if not result:
        print("ERROR: invalid token", file=sys.stderr)
        sys.exit(1)
    elif result[0] != 'admin':
        print("ERROR: forbidden", file=sys.stderr)
        sys.exit(1)

    cursor.execute("SELECT * FROM tasks")
    rows = cursor.fetchall()

    if sys.stdin.isatty():
        for row in rows:
            print(f"{row[0]}|{row[1]}|{row[2]}|{row[3]}")
    else:
        query_line = sys.stdin.readline().strip()
        if not query_line:
            for row in rows:
                print(f"{row[0]}|{row[1]}|{row[2]}|{row[3]}")
        else:
            column, value = re.split(r'=', query_line, 1)
            column = column.strip()
            value = value.strip()

            if column not in ['id', 'title', 'status', 'owner']:
                sys.exit(1)

            cursor.execute(f"SELECT * FROM tasks WHERE {column} = ?", (value,))
            for row in cursor.fetchall():
                print(f"{row[0]}|{row[1]}|{row[2]}|{row[3]}")

    conn.close()

if __name__ == "__main__":
    main()
